    @Test void bornCurrentImageAfterDroppingEveryColumnRetainsActivatedEmptySchemaAcrossColdReopen()throws Exception {
        Path imagePath=root.resolve("empty-schema-image"),receiverPath=root.resolve("empty-schema-receiver");NativeCurrentRangeRecovery registration;
        try(var source=helper.new Fixture(root.resolve("empty-schema-source"),helper.first,"source-")){var directory=source.definition.targetDirectory();int n=0;
            for(var column:List.copyOf(source.child.installedSchema().columns())){var old=source.child.installedSchema();var columns=old.columns().stream().filter(value->!value.columnId().equals(column.columnId())).toList();var target=new DistributedSchema(old.clusterId(),old.databaseId(),old.domainId(),old.schemaEpoch()+1,old.routingPrefixBytes(),columns);var change=new SchemaChange.Definition(new UUID(6,23000+n),new OperationId(new UUID(7,23000+n),1,0),directory,old,target);var names=new HashMap<>(source.pool.schemaPhysicalNames(source.child));names.remove(column.columnId());for(var child:source.children){long next=child.applied().index()+1;child.applySchemaFence(new ApplyPosition(1,next),change.header());var installed=source.pool.installSchema(child,new ApplyPosition(1,next+1),change,names,Set.of());child.applySchemaActivation(new ApplyPosition(1,next+2),installed.proof(),helper.catalogue,new ApplyPosition(1,80+n));}directory=change.targetDirectory();n++;}
            assertTrue(source.child.installedSchema().columns().isEmpty());var image=NativeRangeImage.write(imagePath,source.child,helper.limits);registration=registration(source.child,directory,image,helper.second,helper.first,"empty-");try(var pool=helper.helper.pool(receiverPath)){var receiver=pool.openCurrentRangeRecovery(registration);receiver.installSnapshot(imagePath,helper.limits);assertFalse(receiver.admissionOpen());receiver.completeCurrentRangeRecovery(registration,image.position(),receiver.configuration());assertTrue(receiver.admissionOpen());assertTrue(receiver.installedSchema().columns().isEmpty());assertTrue(pool.schemaPhysicalNames(receiver).isEmpty());}
        }
        try(var pool=helper.helper.pool(receiverPath)){var receiver=pool.openCurrentRangeRecovery(registration);assertTrue(receiver.admissionOpen());assertTrue(receiver.installedSchema().columns().isEmpty());NativeRangeImage.write(root.resolve("empty-export"),receiver,helper.limits);}
    }

    NativeCurrentRangeRecovery withNames(NativeCurrentRangeRecovery registration,Map<UUID,String> names){return new NativeCurrentRangeRecovery(registration.transferId(),registration.catalogue(),registration.catalogueCut(),registration.directory(),registration.schema(),registration.groupId(),registration.receiver(),registration.sourceOwner(),registration.imageCut(),registration.imageHash(),registration.configurationTerm(),registration.configurationIndex(),registration.sourceConfiguration(),registration.origin(),names,registration.mergeColumns(),registration.sourceSchemaRows());}
    @Test void invalidReceiverAliasesRejectBeforeAnyRegistrationForceAndDoNotPoisonExactValidRetry()throws Exception {
        try(var source=helper.new Fixture(root.resolve("alias-source"),helper.first,"source-")){source.child.apply(new ApplyPosition(1,2),source.write(8));var image=NativeRangeImage.write(root.resolve("alias-image"),source.child,helper.limits);var registration=registration(source.child,source.definition.targetDirectory(),image,helper.second,helper.first,"current-");
            try(var pool=helper.helper.pool(root.resolve("reserved-receiver"))){var forces=new java.util.concurrent.atomic.AtomicInteger();pool.currentRecoveryForceObserver(after->forces.incrementAndGet());var names=new HashMap<>(registration.physicalNames());names.put(names.keySet().iterator().next(),DistributedStoragePool.STATE_COLUMN);assertThrows(IllegalArgumentException.class,()->pool.openCurrentRangeRecovery(withNames(registration,names)));assertEquals(0,forces.get());assertTrue(pool.currentRangeRecoveries().isEmpty());assertFalse(pool.persistedRangeGroups(8).contains(registration.groupId()));assertNull(pool.openCurrentRangeRecovery(registration).applied());}
            try(var pool=helper.helper.pool(root.resolve("bound-receiver"))){var right=source.definition.targets().getLast();var boundNames=helper.names("bound-");pool.openRange(new RangeOwnership.Owner(right.groupId(),right.rangeEpoch()),new RangeOwnership.Interval(registration.schema().domainId(),registration.schema().columnIds(),right.lowerInclusive(),right.upperExclusive()),registration.schema().digest(),boundNames,Set.of());var forces=new java.util.concurrent.atomic.AtomicInteger();pool.currentRecoveryForceObserver(after->forces.incrementAndGet());assertThrows(IllegalArgumentException.class,()->pool.openCurrentRangeRecovery(registration));assertEquals(0,forces.get());assertTrue(pool.currentRangeRecoveries().isEmpty());assertFalse(pool.persistedRangeGroups(8).contains(registration.groupId()));assertNull(pool.openCurrentRangeRecovery(withNames(registration,boundNames)).applied());}
        }
    }
    @Test void deterministicSharedRegistryCapacityRejectionDoesNotCreateUnknownForceOrBlockExistingOwner()throws Exception {
        try(var pool=helper.helper.pool(root.resolve("capacity-receiver"))){var forces=new java.util.concurrent.atomic.AtomicInteger();pool.currentRecoveryForceObserver(after->forces.incrementAndGet());NativeCurrentRangeRecovery first=null;ReplicatedRangeStore firstStore=null;
            for(int n=0;n<129;n++){var schema=new DistributedSchema(new UUID(9,1),new UUID(9,2),new UUID(10,n),1,0,List.of());var range=new RangeDescriptor(new UUID(11,n),new UUID(12,n),1,1,null,null,RangeDescriptor.TopologyState.ACTIVE,List.of(helper.first,helper.second));var directory=new RangeDirectory(schema.clusterId(),schema.databaseId(),schema.domainId(),schema.schemaEpoch(),schema.digest(),1,Set.of(),0,List.of(range));var registration=new NativeCurrentRangeRecovery(new UUID(13,n),helper.catalogue,new ApplyPosition(1,20),directory,schema,range.groupId(),helper.second,helper.first,new ApplyPosition(1,1),new byte[32],0,-1,new byte[]{1},null,Map.of(),Set.of(),Map.of());if(n<128){var store=pool.openCurrentRangeRecovery(registration);if(n==0){first=registration;firstStore=store;}}else{int before=forces.get();assertThrows(IllegalStateException.class,()->pool.openCurrentRangeRecovery(registration));assertEquals(before,forces.get());assertFalse(pool.persistedRangeGroups(256).contains(registration.groupId()));}}
            assertEquals(128,pool.currentRangeRecoveries().size());assertSame(firstStore,pool.openCurrentRangeRecovery(first));assertEquals(256,forces.get());
        }
    }

